function SpiritTypeahead({ value, onChange, demons, mode, placeholder, isDark = true }: {
  value: string
  onChange: (val: string) => void
  demons: any[]
  mode: 'single' | 'multi'
  placeholder?: string
  isDark?: boolean
}) {
  const [localInput, setLocalInput] = useState('')
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)

  const selected = mode === 'multi' ? value.split(',').map(s => s.trim()).filter(Boolean) : []
  const filterText = mode === 'single' ? value : localInput
  const suggestions = filterText.length > 0
    ? demons
        .filter(d => d.name && d.name.toLowerCase().includes(filterText.toLowerCase()))
        .filter(d => mode === 'multi' ? !selected.includes(d.name) : true)
        .slice(0, 8)
    : []

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const adBdr  = isDark ? BDR : '#D8D1BE'
  const adTxt  = isDark ? TXT : '#1F1B12'
  const adDim  = isDark ? DIM : '#574B33'
  const adGold = isDark ? G   : '#604408'
  const inp: React.CSSProperties = {
    width: '100%', boxSizing: 'border-box' as const, background: isDark ? '#0a0813' : '#fff',
    border: `1px solid ${adBdr}`, borderRadius: 6, padding: '9px 11px',
    color: adTxt, fontFamily: crimson, fontSize: 13, outline: 'none',
  }

  const handleSelect = (name: string) => {
    if (mode === 'single') {
      onChange(name)
    } else {
      onChange([...selected, name].join(', '))
      setLocalInput('')
    }
    setOpen(false)
  }

  return (
    <div ref={ref} style={{ position: 'relative' }}>
      {mode === 'multi' && selected.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap' as const, gap: 6, marginBottom: 8 }}>
          {selected.map(name => (
            <span key={name} style={{ display: 'inline-flex', alignItems: 'center', gap: 4, background: 'rgba(201,168,76,0.1)', border: `1px solid rgba(201,168,76,0.3)`, borderRadius: 20, padding: '3px 10px', fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.06em' }}>
              {name}
              <button onMouseDown={e => { e.preventDefault(); onChange(selected.filter(s => s !== name).join(', ')) }}
                style={{ background: 'none', border: 'none', color: adGold, cursor: 'pointer', padding: 0, fontSize: 11, lineHeight: 1 }}>✕</button>
            </span>
          ))}
        </div>
      )}
      <input
        value={mode === 'single' ? value : localInput}
        onChange={e => {
          if (mode === 'single') { onChange(e.target.value); setOpen(true) }
          else { setLocalInput(e.target.value); setOpen(true) }
        }}
        onFocus={() => { if (filterText.length > 0) setOpen(true) }}
        placeholder={placeholder || (mode === 'multi' ? 'Type spirit name to add...' : 'Type to search...')}
        style={inp}
      />
      {open && suggestions.length > 0 && (
        <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 100, background: isDark ? '#1a1625' : '#fff', border: '1px solid rgba(201,168,76,0.3)', borderRadius: 6, marginTop: 2, maxHeight: 200, overflowY: 'auto' as const, boxShadow: '0 8px 24px rgba(0,0,0,0.5)' }}>
          {suggestions.map(d => (
            <div key={d.airtableId || d.name}
              onMouseDown={e => { e.preventDefault(); handleSelect(d.name) }}
              onMouseEnter={e => { (e.currentTarget as HTMLDivElement).style.background = 'rgba(201,168,76,0.1)'; (e.currentTarget as HTMLDivElement).style.color = adGold }}
              onMouseLeave={e => { (e.currentTarget as HTMLDivElement).style.background = 'transparent'; (e.currentTarget as HTMLDivElement).style.color = adDim }}
              style={{ padding: '8px 12px', cursor: 'pointer', fontFamily: cinzel, fontSize: 10, color: adDim, letterSpacing: '0.06em', display: 'flex', alignItems: 'center', gap: 8 }}>
              {d.name}
              {d.type && <span style={{ fontSize: 8, opacity: 0.5 }}>{d.type}</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

function SpiritEditForm({ fields, setField, onSave, onCancel, saving, msg, demons = [], getToken, isDark = true, spiritId }: {
  fields: Record<string, string>
  setField: (name: string, val: string) => void
  onSave: () => void
  onCancel: () => void
  saving: boolean
  msg: string
  demons?: any[]
  getToken?: () => Promise<string | null>
  isDark?: boolean
  spiritId?: string
}) {
  const [loadingEquivalents, setLoadingEquivalents] = useState(false)
  const [equivalentSuggestions, setEquivalentSuggestions] = useState<any[]>([])
  const [equivalentSummary, setEquivalentSummary] = useState('')
  const [showEquivalentSuggestions, setShowEquivalentSuggestions] = useState(false)
  const [rcSnaps, setRcSnaps] = useState<any[]>([])
  const [rcLoading, setRcLoading] = useState(false)
  const [rcExpanded, setRcExpanded] = useState<Set<string>>(new Set())
  const [rcRestoring, setRcRestoring] = useState<Set<string>>(new Set())
  const [rcConfirm, setRcConfirm] = useState<string | null>(null)
  const [rcMsg, setRcMsg] = useState('')

  useEffect(() => {
    if (!spiritId || !getToken) return
    setRcLoading(true)
    ;(async () => {
      try {
        const token = await getToken()
        const res = await fetch(`/api/spirit-apply-snapshots?spiritId=${encodeURIComponent(spiritId)}&limit=10`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        const data = await res.json()
        setRcSnaps(data.snapshots || [])
      } catch (e) { console.error('[RECENT CHANGES] fetch error:', e) }
      setRcLoading(false)
    })()
  }, [spiritId])

  async function handleRestore(snapshotId: string) {
    if (!getToken) return
    setRcRestoring(prev => new Set(prev).add(snapshotId))
    setRcMsg('')
    try {
      const token = await getToken()
      const res = await fetch('/api/spirit-restore-snapshot', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ snapshotId }),
      })
      const d = await res.json()
      if (res.ok) {
        const CAMEL_TO_FORM: Record<string, string> = {
          name: INTEL_NAME_F, aka: 'Also Known As', description: 'Description',
          manifestation: 'Manifestiation', scripture: 'Scripture Reference',
          entryPoints: 'Entry Points', sourceOrigin: 'Source / Orgin',
          kingdom: 'Kingdom', strongman: 'Strongman', legalRights: 'Legal Rights',
          symptoms: 'Symptoms', companionSpirits: 'Companion Spirits',
          wriNotes: 'WRI Exorcist Notes', assignment: 'Assignment',
          hierarchyCategory: 'Hierarchy Category', parentStrongman: 'Parent Strongman',
          deliveranceSequence: 'Deliverance Sequence', operationalNotes: 'Operational Notes',
          primaryBattlefield: 'Primary Battlefield',
          personalityPresentation: 'Typical Personality Presentation',
          counterScriptures: 'Counter Scriptures', phonetic: 'Phonetic',
          images: 'Images', relatedSpirits: 'Related Spirits',
          biblicalRank: 'Biblical Rank', caseType: 'Case Type',
          isGenerational: 'Is Generational', isTerritorial: 'Is Territorial',
          clusterSpirits: 'Cluster Spirits', legalRightsFramework: 'Legal Rights Framework',
          institutionalExpression: 'Institutional Expression',
          sessionIndicators: 'Session Indicators', resistanceSignature: 'Resistance Signature',
          demonicAgreements: 'Demonic Agreements', transmissionVectors: 'Transmission Vectors',
          etymologyNotes: 'Etymology Notes', archaeologyNotes: 'Archaeology Notes',
          scriptureContext: 'Scripture Context', prayerPoints: 'Prayer Points',
          aftercareNotes: 'Aftercare Notes', equivalents: 'Equivalent Spirits',
        }
        const formKey = CAMEL_TO_FORM[d.restoredField]
        if (formKey) {
          let formVal: string
          if (typeof d.restoredValue === 'boolean') formVal = String(d.restoredValue)
          else if (Array.isArray(d.restoredValue)) formVal = (d.restoredValue as any[]).join('\n')
          else if (d.restoredValue == null) formVal = ''
          else formVal = String(d.restoredValue)
          setField(formKey, formVal)
        } else {
          console.warn('[handleRestore] no form field for snapshot field:', d.restoredField)
        }
        setRcSnaps(prev => prev.map(s => s.id === snapshotId ? { ...s, restored_at: new Date().toISOString() } : s))
        setRcMsg(`Restored "${EH_FIELD_LABELS[d.restoredField] || d.restoredField}" successfully.`)
        setRcConfirm(null)
      } else {
        setRcMsg(`Error: ${d.error || 'Unknown'}`)
      }
    } catch (e: any) {
      setRcMsg(`Error: ${e?.message || String(e)}`)
    }
    setRcRestoring(prev => { const next = new Set(prev); next.delete(snapshotId); return next })
  }
  const adBdr  = isDark ? BDR : '#D8D1BE'
  const adTxt  = isDark ? TXT : '#1F1B12'
  const adDim  = isDark ? DIM : '#574B33'
  const adGold = isDark ? G   : '#604408'
  const i: React.CSSProperties = {
    width: '100%', boxSizing: 'border-box', background: isDark ? '#0a0813' : '#fff',
    border: `1px solid ${adBdr}`, borderRadius: 6, padding: '9px 11px',
    color: adTxt, fontFamily: crimson, fontSize: 13, outline: 'none',
  }
  const l: React.CSSProperties = {
    display: 'block', fontFamily: cinzel, fontSize: 9,
    letterSpacing: '0.12em', color: adDim, textTransform: 'uppercase', marginBottom: 5,
  }
  const f = (name: string) => fields[name] || ''
  const ti = (name: string) => <input value={f(name)} onChange={e => setField(name, e.target.value)} style={i} />
  const ta = (name: string, rows = 3) => (
    <textarea value={f(name)} onChange={e => setField(name, e.target.value)} rows={rows}
      style={{ ...i, resize: 'vertical' as const }} />
  )

  async function lookupEquivalents() {
    if (!getToken) return
    setLoadingEquivalents(true)
    setShowEquivalentSuggestions(false)
    try {
      const token = await getToken()
      const res = await fetch('/api/spirit-equivalents', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...(spiritId ? { spiritId } : {}),
          spiritName: f(INTEL_NAME_F),
          kingdom: f('Kingdom'),
          description: f('Description'),
          aka: f('Also Known As'),
        }),
      })
      const data = await res.json()
      if (data.equivalents?.length > 0) {
        setEquivalentSuggestions(data.equivalents)
        setEquivalentSummary(data.summary || '')
        setShowEquivalentSuggestions(true)
      } else {
        setEquivalentSuggestions([])
        setEquivalentSummary('No cross-cultural equivalents found with sufficient confidence.')
        setShowEquivalentSuggestions(true)
      }
    } catch (err) {
      console.error('[lookupEquivalents]', err)
    } finally {
      setLoadingEquivalents(false)
    }
  }
  return (
    <div style={{ background: isDark ? '#09080f' : '#F7F5F0', border: `1px solid ${adBdr}`, borderRadius: 8, padding: 20 }}>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Name *</label>{ti(INTEL_NAME_F)}</div>
        <div><label style={l}>Also Known As</label>{ti('Also Known As')}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Description</label>{ta('Description')}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Manifestiation</label>{ta('Manifestiation')}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Entry Points</label>{ta('Entry Points')}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Legal Rights</label>{ta('Legal Rights')}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Symptoms</label>{ta('Symptoms')}</div>
        <div>
          <label style={l}>Companion Spirits</label>
          <SpiritTypeahead mode="multi" value={f('Companion Spirits')} onChange={v => setField('Companion Spirits', v)} demons={demons} placeholder="Type spirit name to add..." isDark={isDark} />
        </div>
        <div>
          <label style={l}>Kingdom</label>
          <select value={f('Kingdom')} onChange={e => setField('Kingdom', e.target.value)} style={{ ...i }}>
            <option value="">Select</option>
            {['Hell', 'Darkness', 'Air', 'Water', 'Earth', 'Witchcraft', 'Occult'].map(k => <option key={k}>{k}</option>)}
          </select>
        </div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>WRI Exorcist Notes</label>{ta('WRI Exorcist Notes')}</div>
        <div>
          <label style={l}>Hierarchy Category</label>
          <select value={f('Hierarchy Category')} onChange={e => setField('Hierarchy Category', e.target.value)} style={{ ...i }}>
            <option value="">Select</option>
            {HIER_CATS.map(c => <option key={c}>{c}</option>)}
          </select>
        </div>
        <div>
          <label style={l}>Parent Strongman</label>
          <SpiritTypeahead mode="single" value={f('Parent Strongman')} onChange={v => setField('Parent Strongman', v)} demons={demons} placeholder="Type to search spirits..." isDark={isDark} />
        </div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Deliverance Sequence</label>{ta('Deliverance Sequence', 4)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Operational Notes</label>{ta('Operational Notes')}</div>
        <div>
          <label style={l}>Primary Battlefield</label>
          <select value={f('Primary Battlefield')} onChange={e => setField('Primary Battlefield', e.target.value)} style={{ ...i }}>
            <option value="">Select</option>
            {BATTLEFIELDS.map(b => <option key={b}>{b}</option>)}
          </select>
        </div>
        <div><label style={l}>Typical Personality Presentation</label>{ti('Typical Personality Presentation')}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Counter Scriptures</label>{ta('Counter Scriptures')}</div>
        <div><label style={l}>Scripture Reference</label>{ti('Scripture Reference')}</div>
        <div><label style={l}>Source / Origin</label>{ti('Source / Orgin')}</div>
        <div><label style={l}>Strongman</label>{ti('Strongman')}</div>
        <div><label style={l}>Assignment</label>{ti('Assignment')}</div>
        <div style={{ gridColumn: '1 / -1' }}>
          <label style={l}>Phonetic Pronunciation</label>
          <div style={{ display: 'flex', gap: 8 }}>
            <input value={f('Phonetic')} onChange={e => setField('Phonetic', e.target.value)}
              placeholder="e.g. BAY-uhl-zee-bub"
              style={{ flex: 1, ...i }} />
            <button
              onClick={() => {
                const ph = f('Phonetic')
                if (ph && 'speechSynthesis' in window) {
                  window.speechSynthesis.cancel()
                  const u = new SpeechSynthesisUtterance(ph)
                  u.rate = 0.75
                  window.speechSynthesis.speak(u)
                }
              }}
              style={{ padding: '6px 12px', background: 'rgba(201,168,76,0.1)', border: `1px solid rgba(201,168,76,0.3)`, borderRadius: 6, color: adGold, fontFamily: cinzel, fontSize: 9, cursor: 'pointer', whiteSpace: 'nowrap' as const }}>
              🔊 Test
            </button>
          </div>
          <div style={{ fontSize: 10, color: adDim, fontFamily: crimson, marginTop: 3, fontStyle: 'italic' }}>
            Use ALL-CAPS syllables, hyphens between. Click Test to hear browser TTS preview.
          </div>
        </div>
        <div style={{ gridColumn: '1 / -1' }}>
          <label style={l}>Historical Image URLs</label>
          <textarea value={f('Images')} onChange={e => setField('Images', e.target.value)}
            placeholder={'One URL per line\nhttps://upload.wikimedia.org/...'}
            rows={3} style={{ ...i, resize: 'vertical' as const }} />
          <div style={{ fontSize: 10, color: adDim, fontFamily: crimson, marginTop: 3, fontStyle: 'italic' }}>
            One image URL per line. Wikimedia Commons, historical manuscripts, etc.
          </div>
        </div>
        <div style={{ gridColumn: '1 / -1' }}>
          <label style={l}>Related Spirits</label>
          <input value={f('Related Spirits')} onChange={e => setField('Related Spirits', e.target.value)}
            placeholder="Comma separated: Jezebel, Ahab, Leviathan"
            style={{ ...i }} />
        </div>

        {/* Biblical Classification Section */}
        <div style={{ gridColumn: '1 / -1', fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.15em', textTransform: 'uppercase' as const, marginBottom: 8, marginTop: 8, paddingTop: 16, paddingBottom: 6, borderTop: `1px solid ${adBdr}`, borderBottom: `1px solid ${adBdr}` }}>⚔ Biblical Classification</div>
        <div>
          <label style={l}>Biblical Rank (Eph. 6:12)</label>
          <select value={f('Biblical Rank')} onChange={e => setField('Biblical Rank', e.target.value)} style={{ ...i }}>
            <option value="">Select</option>
            {['Principality', 'Power', 'Ruler of Darkness', 'Spiritual Wickedness in High Places', 'Fallen Angel', 'Demon', 'Familiar Spirit', 'Spirit of Infirmity'].map(r => <option key={r}>{r}</option>)}
          </select>
        </div>
        <div>
          <label style={l}>Case Type</label>
          <select value={f('Case Type')} onChange={e => setField('Case Type', e.target.value)} style={{ ...i }}>
            <option value="">Select</option>
            {['Personal Deliverance', 'Generational/Bloodline', 'Territorial/Regional', 'Institutional', 'Atmospheric/Intercessory', 'Multiple'].map(r => <option key={r}>{r}</option>)}
          </select>
        </div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Transmission Vectors</label>{ta('Transmission Vectors', 2)}</div>
        <div style={{ gridColumn: '1 / -1', display: 'flex', gap: 24 }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer' }}>
            <input type="checkbox" checked={f('Is Generational') === 'true'} onChange={e => setField('Is Generational', e.target.checked ? 'true' : 'false')} style={{ accentColor: adGold, width: 14, height: 14 }} />
            <span style={{ fontFamily: crimson, fontSize: 13, color: adTxt }}>Primarily Generational/Bloodline</span>
          </label>
          <label style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer' }}>
            <input type="checkbox" checked={f('Is Territorial') === 'true'} onChange={e => setField('Is Territorial', e.target.checked ? 'true' : 'false')} style={{ accentColor: adGold, width: 14, height: 14 }} />
            <span style={{ fontFamily: crimson, fontSize: 13, color: adTxt }}>Primarily Territorial/Regional</span>
          </label>
        </div>

        {/* Operational Intelligence Section */}
        <div style={{ gridColumn: '1 / -1', fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.15em', textTransform: 'uppercase' as const, marginBottom: 8, marginTop: 8, paddingTop: 16, paddingBottom: 6, borderTop: `1px solid ${adBdr}`, borderBottom: `1px solid ${adBdr}` }}>🔍 Operational Intelligence</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Session Indicators</label>{ta('Session Indicators', 3)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Resistance Signature</label>{ta('Resistance Signature', 2)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Demonic Agreements / Lies Planted</label>{ta('Demonic Agreements', 3)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Cluster Spirits</label>{ta('Cluster Spirits', 3)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Legal Rights Framework</label>{ta('Legal Rights Framework', 3)}</div>

        {/* Scholarly Section */}
        <div style={{ gridColumn: '1 / -1', fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.15em', textTransform: 'uppercase' as const, marginBottom: 8, marginTop: 8, paddingTop: 16, paddingBottom: 6, borderTop: `1px solid ${adBdr}`, borderBottom: `1px solid ${adBdr}` }}>📚 Scholarly Research</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Etymology Notes</label>{ta('Etymology Notes', 3)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Archaeology Notes</label>{ta('Archaeology Notes', 3)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Scripture Context</label>{ta('Scripture Context', 4)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Institutional Expression</label>{ta('Institutional Expression', 2)}</div>

        {/* Ministry Section */}
        <div style={{ gridColumn: '1 / -1', fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.15em', textTransform: 'uppercase' as const, marginBottom: 8, marginTop: 8, paddingTop: 16, paddingBottom: 6, borderTop: `1px solid ${adBdr}`, borderBottom: `1px solid ${adBdr}` }}>🙏 Ministry Application</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Prayer Points</label>{ta('Prayer Points', 3)}</div>
        <div style={{ gridColumn: '1 / -1' }}><label style={l}>Aftercare Notes</label>{ta('Aftercare Notes', 3)}</div>

        {/* Cross-Cultural Equivalents Section */}
        <div style={{ gridColumn: '1 / -1', fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.15em', textTransform: 'uppercase' as const, marginBottom: 8, marginTop: 8, paddingTop: 16, paddingBottom: 6, borderTop: `1px solid ${adBdr}`, borderBottom: `1px solid ${adBdr}` }}>🌐 Cross-Cultural Equivalents</div>
        <div style={{ gridColumn: '1 / -1' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
            <label style={{ ...l, marginBottom: 0 }}>EQUIVALENT SPIRITS</label>
            {getToken && (
              <button
                onClick={lookupEquivalents}
                disabled={loadingEquivalents}
                style={{ background: 'transparent', border: `1px solid rgba(201,168,76,0.3)`, borderRadius: 4, padding: '3px 10px', fontSize: 9, color: adGold, fontFamily: cinzel, cursor: 'pointer', letterSpacing: '0.08em', opacity: loadingEquivalents ? 0.5 : 1 }}>
                {loadingEquivalents ? 'Looking up...' : '✦ AI Lookup'}
              </button>
            )}
          </div>

          {showEquivalentSuggestions && (
            <div style={{ background: 'rgba(201,168,76,0.04)', border: '1px solid rgba(201,168,76,0.2)', borderRadius: 6, padding: 12, marginBottom: 8 }}>
              {equivalentSummary && (
                <div style={{ fontFamily: crimson, fontSize: 12, color: 'rgba(240,232,216,0.7)', fontStyle: 'italic', marginBottom: 10 }}>
                  {equivalentSummary}
                </div>
              )}
              {equivalentSuggestions.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginBottom: 8 }}>
                  {equivalentSuggestions.map((eq, idx) => (
                    <div key={idx} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: 'rgba(201,168,76,0.06)', border: '1px solid rgba(201,168,76,0.15)', borderRadius: 4, padding: '6px 10px' }}>
                      <div>
                        <span style={{ fontFamily: cinzel, fontSize: 11, color: adGold }}>{eq.name}</span>
                        <span style={{ fontFamily: cinzel, fontSize: 9, color: 'rgba(201,168,76,0.5)', marginLeft: 8 }}>({eq.tradition})</span>
                        {eq.notes && (
                          <div style={{ fontFamily: crimson, fontSize: 11, color: 'rgba(240,232,216,0.5)', fontStyle: 'italic', marginTop: 2 }}>
                            {eq.notes}
                          </div>
                        )}
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
                        <span style={{ fontFamily: cinzel, fontSize: 9, color: 'rgba(201,168,76,0.4)' }}>{eq.confidence}/10</span>
                        <button
                          onClick={() => {
                            const line = eq.tradition ? `${eq.name} (${eq.tradition})` : eq.name
                            setField('Equivalent Spirits', f('Equivalent Spirits').trim() ? `${f('Equivalent Spirits').trim()}\n${line}` : line)
                          }}
                          style={{ background: 'rgba(201,168,76,0.15)', border: '1px solid rgba(201,168,76,0.4)', borderRadius: 4, padding: '3px 8px', fontSize: 9, color: adGold, fontFamily: cinzel, cursor: 'pointer', letterSpacing: '0.06em', whiteSpace: 'nowrap' as const }}>
                          + ADD
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
              <button
                onClick={() => {
                  const allLines = equivalentSuggestions.map(eq => eq.tradition ? `${eq.name} (${eq.tradition})` : eq.name).join('\n')
                  setField('Equivalent Spirits', f('Equivalent Spirits').trim() ? `${f('Equivalent Spirits').trim()}\n${allLines}` : allLines)
                  setShowEquivalentSuggestions(false)
                }}
                style={{ background: 'rgba(201,168,76,0.12)', border: '1px solid rgba(201,168,76,0.3)', borderRadius: 4, padding: '5px 12px', fontSize: 9, color: adGold, fontFamily: cinzel, cursor: 'pointer', letterSpacing: '0.08em', width: '100%' }}>
                + ADD ALL TO FIELD
              </button>
            </div>
          )}

          <textarea value={f('Equivalent Spirits')} onChange={e => setField('Equivalent Spirits', e.target.value)}
            rows={4} placeholder={'One equivalent per line, e.g.:\nAshtoreth (Canaanite)\nVenus (Roman)\nIshtar (Babylonian)'}
            style={{ ...i, resize: 'vertical' as const }} />
          <div style={{ fontSize: 10, color: adDim, fontFamily: crimson, marginTop: 3, fontStyle: 'italic' }}>
            One equivalent per line. Include tradition in parentheses.
          </div>
        </div>
      </div>

      {/* Recent Changes (per-field apply history with restore) */}
      {spiritId && getToken && (
        <div style={{ marginTop: 20, paddingTop: 16, borderTop: `1px solid ${adBdr}` }}>
          <div style={{ fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.15em', textTransform: 'uppercase' as const, marginBottom: 12 }}>
            🕐 Recent Changes
          </div>
          {rcLoading ? (
            <div style={{ fontFamily: crimson, fontSize: 12, color: adDim, fontStyle: 'italic' }}>Loading...</div>
          ) : rcSnaps.length === 0 ? (
            <div style={{ fontFamily: crimson, fontSize: 12, color: adDim, fontStyle: 'italic' }}>No changes recorded yet. Recent edits will appear here.</div>
          ) : (
            <>
              {rcSnaps.map(s => {
                const isExpanded  = rcExpanded.has(s.id)
                const isRestoring = rcRestoring.has(s.id)
                const whenStr     = new Date(s.applied_at).toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' })
                const label       = EH_FIELD_LABELS[s.field_name] || s.field_name
                return (
                  <div key={s.id} style={{ borderBottom: `1px solid ${adBdr}`, paddingBottom: 10, marginBottom: 10 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' as const }}>
                      <span style={{ fontFamily: cinzel, fontSize: 9, color: adGold, letterSpacing: '0.06em', minWidth: 120 }}>{label}</span>
                      <span style={{ fontFamily: crimson, fontSize: 11, color: adDim }}>{whenStr}</span>
                      {(() => {
                        const src = s.source || (s.job_id ? 'enrich' : null)
                        if (src === 'enrich')         return <span style={{ fontFamily: cinzel, fontSize: 8, color: '#a78bfa', letterSpacing: '0.04em', background: 'rgba(167,139,250,0.12)', padding: '1px 5px', borderRadius: 2, border: '1px solid rgba(167,139,250,0.25)' }}>AI ENRICHMENT</span>
                        if (src === 'library_enrich') return <span style={{ fontFamily: cinzel, fontSize: 8, color: '#60a5fa', letterSpacing: '0.04em', background: 'rgba(96,165,250,0.12)', padding: '1px 5px', borderRadius: 2, border: '1px solid rgba(96,165,250,0.25)' }}>LIBRARY</span>
                        if (src === 'manual')         return <span style={{ fontFamily: cinzel, fontSize: 8, color: adDim, letterSpacing: '0.04em', background: 'rgba(201,168,76,0.06)', padding: '1px 5px', borderRadius: 2, border: `1px solid ${adBdr}` }}>MANUAL EDIT</span>
                        if (src === 'taxonomy')       return <span style={{ fontFamily: cinzel, fontSize: 8, color: adGold, letterSpacing: '0.04em', background: 'rgba(201,168,76,0.1)', padding: '1px 5px', borderRadius: 2, border: '1px solid rgba(201,168,76,0.25)' }}>TAXONOMY</span>
                        return <span style={{ fontFamily: cinzel, fontSize: 8, color: adDim, letterSpacing: '0.04em', background: 'rgba(120,120,120,0.1)', padding: '1px 5px', borderRadius: 2, border: `1px solid ${adBdr}` }}>EDIT</span>
                      })()}
                      {s.restored_at ? (
                        <span style={{ fontFamily: cinzel, fontSize: 8, color: '#4ade80', letterSpacing: '0.06em', background: 'rgba(74,222,128,0.1)', padding: '2px 6px', borderRadius: 3, border: '1px solid rgba(74,222,128,0.2)' }}>RESTORED</span>
                      ) : (
                        <>
                          <button
                            onClick={() => setRcExpanded(prev => { const next = new Set(prev); isExpanded ? next.delete(s.id) : next.add(s.id); return next })}
                            style={{ background: 'transparent', border: `1px solid ${adBdr}`, borderRadius: 3, padding: '2px 8px', fontFamily: cinzel, fontSize: 8, color: adDim, cursor: 'pointer', letterSpacing: '0.06em' }}>
                            {isExpanded ? 'HIDE' : 'VIEW'}
                          </button>
                          {rcConfirm === s.id ? (
                            <>
                              <span style={{ fontFamily: crimson, fontSize: 11, color: '#f87171' }}>Confirm restore?</span>
                              <button onClick={() => handleRestore(s.id)} disabled={isRestoring}
                                style={{ background: '#f87171', border: 'none', borderRadius: 3, padding: '2px 8px', fontFamily: cinzel, fontSize: 8, color: '#fff', cursor: isRestoring ? 'not-allowed' : 'pointer', letterSpacing: '0.06em' }}>
                                {isRestoring ? '...' : 'YES'}
                              </button>
                              <button onClick={() => setRcConfirm(null)}
                                style={{ background: 'transparent', border: `1px solid ${adBdr}`, borderRadius: 3, padding: '2px 8px', fontFamily: cinzel, fontSize: 8, color: adDim, cursor: 'pointer', letterSpacing: '0.06em' }}>
                                NO
                              </button>
                            </>
                          ) : (
                            <button onClick={() => setRcConfirm(s.id)}
                              style={{ background: 'transparent', border: '1px solid rgba(248,113,113,0.3)', borderRadius: 3, padding: '2px 8px', fontFamily: cinzel, fontSize: 8, color: '#f87171', cursor: 'pointer', letterSpacing: '0.06em' }}>
                              RESTORE
                            </button>
                          )}
                        </>
                      )}
                    </div>
                    {isExpanded && (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginTop: 8, padding: '8px 10px', background: isDark ? '#0a0813' : '#f5f3ef', borderRadius: 4, border: `1px solid ${adBdr}` }}>
                        <div>
                          <div style={{ fontFamily: cinzel, fontSize: 8, color: adDim, letterSpacing: '0.08em', marginBottom: 4 }}>PRIOR VALUE</div>
                          <div style={{ fontFamily: crimson, fontSize: 12, color: adDim, lineHeight: 1.5 }}>
                            {s.prior_value !== null && s.prior_value !== undefined
                              ? (typeof s.prior_value === 'string' ? s.prior_value : JSON.stringify(s.prior_value))
                              : <em>empty</em>}
                          </div>
                        </div>
                        <div>
                          <div style={{ fontFamily: cinzel, fontSize: 8, color: adGold, letterSpacing: '0.08em', marginBottom: 4 }}>APPLIED VALUE</div>
                          <div style={{ fontFamily: crimson, fontSize: 12, color: adTxt, lineHeight: 1.5 }}>
                            {s.applied_value !== null && s.applied_value !== undefined
                              ? (typeof s.applied_value === 'string' ? s.applied_value : JSON.stringify(s.applied_value))
                              : <em>empty</em>}
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )
              })}
              {rcMsg && <div style={{ fontFamily: crimson, fontSize: 12, color: rcMsg.startsWith('Error') ? '#f87171' : '#4ade80', marginTop: 4 }}>{rcMsg}</div>}
            </>
          )}
        </div>
      )}

      {msg && <div style={{ fontFamily: crimson, fontSize: 13, color: msg.startsWith('✓') ? '#4ade80' : '#f87171', marginTop: 12 }}>{msg}</div>}
      <div style={{ display: 'flex', gap: 10, marginTop: 16 }}>
        <button onClick={onSave} disabled={saving}
          style={{ background: saving ? 'rgba(201,168,76,0.2)' : adGold, color: saving ? adDim : '#0D0B14', border: 'none', borderRadius: 6, padding: '9px 22px', fontFamily: cinzel, fontSize: 10, letterSpacing: '0.1em', cursor: saving ? 'not-allowed' : 'pointer' }}>
          {saving ? 'Saving...' : '✓ Save'}
        </button>
        <button onClick={onCancel}
          style={{ background: 'transparent', color: adDim, border: `1px solid ${adBdr}`, borderRadius: 6, padding: '9px 18px', fontFamily: cinzel, fontSize: 10, letterSpacing: '0.1em', cursor: 'pointer' }}>
          Cancel
        </button>
      </div>
    </div>
  )
}

